const R6_PAIRING_TICKET_LIFETIME_NS_V1: u64 = 300 * 1_000_000_000;
// Signed R6 documents are prepared into distinct durable Keychain accounts. Their validity
// begins only after this fixed commit lead, so predecessor, continuation, and Available-state
// CAS all complete before any of the exact 300-second admission window can be consumed.
const R6_PAIRING_PREPARE_LEAD_NS_V1: u64 = 10 * 1_000_000_000;
const R6_PAIRING_CONTINUATION_COMMAND_V1: &str = "guest-publisher-pairing-direct-interactive-v1";
/// Lifecycle effects may take materially longer than the bounded FD3 bootstrap frame.  This
/// is still a fixed executor-owned ceiling, never a caller supplied timeout.
const MAC_LIMA_EFFECT_TIMEOUT_V1: Duration = Duration::from_secs(300);
const MAC_LIMA_TOOL_PATH_V1: &str = "/usr/local/bin/limactl";
const MAC_LIMA_CHILD_PATH_V1: &str = "/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin";
const MAC_LIMA_PROFILE_CHILD_PATH_V1: &str = "/dev/fd/3";
const MAC_LIMA_PROFILE_CHILD_FD_V1: libc::c_int = 3;
const MAC_LIMA_POST_PM_STAGING_ROOT_V1: &str = "/var/lib/substrate/.substrate-lifecycle-v1/staged";
// The descriptor-bound source is streamed into a same-directory temporary object and published
// atomically. A partial temp from interruption is either proven exact and completed, or removed
// only after no-follow root-owned verification. The final generation key is never written directly.
const MAC_LIMA_POST_PM_STDIN_TRANSFER_SCRIPT_V1: &str = r#"import hashlib, os, stat, sys
target, expected_sha, expected_size = sys.argv[1], sys.argv[2], int(sys.argv[3])
root = '/var/lib/substrate/.substrate-lifecycle-v1/staged/'
if not target.startswith(root) or '\x00' in target or '/..' in target:
    raise SystemExit(91)
parent, leaf = os.path.split(target)
if not leaf or leaf in ('.', '..'):
    raise SystemExit(91)
os.makedirs(parent, mode=0o700, exist_ok=True)
for component in (root.rstrip('/'), parent):
    meta = os.lstat(component)
    if not stat.S_ISDIR(meta.st_mode) or stat.S_ISLNK(meta.st_mode) or meta.st_uid != 0 or meta.st_gid != 0:
        raise SystemExit(92)
    os.chmod(component, 0o700)
dirfd = os.open(parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
def read_exact(name, required_mode):
    fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=dirfd)
    try:
        meta = os.fstat(fd)
        digest = hashlib.sha256()
        size = 0
        while True:
            block = os.read(fd, 1024 * 1024)
            if not block: break
            size += len(block); digest.update(block)
        if (not stat.S_ISREG(meta.st_mode) or meta.st_nlink != 1 or meta.st_uid != 0
                or meta.st_gid != 0 or stat.S_IMODE(meta.st_mode) != required_mode
                or size != expected_size or digest.hexdigest() != expected_sha):
            raise SystemExit(93)
    finally:
        os.close(fd)
try:
    try:
        read_exact(leaf, 0o444)
        final_exists = True
    except FileNotFoundError:
        final_exists = False
    if final_exists:
        digest = hashlib.sha256(); size = 0
        while True:
            block = sys.stdin.buffer.read(1024 * 1024)
            if not block: break
            size += len(block); digest.update(block)
        if size != expected_size or digest.hexdigest() != expected_sha:
            raise SystemExit(95)
    else:
        temp = leaf + '.partial'
        try:
            tempfd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600, dir_fd=dirfd)
        except FileExistsError:
            tempfd = os.open(temp, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=dirfd)
            meta = os.fstat(tempfd)
            os.close(tempfd)
            if not stat.S_ISREG(meta.st_mode) or meta.st_nlink != 1 or meta.st_uid != 0 or meta.st_gid != 0:
                raise SystemExit(94)
            os.unlink(temp, dir_fd=dirfd)
            tempfd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600, dir_fd=dirfd)
        digest = hashlib.sha256(); size = 0
        with os.fdopen(tempfd, 'wb', closefd=True) as output:
            while True:
                block = sys.stdin.buffer.read(1024 * 1024)
                if not block: break
                size += len(block); digest.update(block); output.write(block)
            output.flush(); os.fchown(output.fileno(), 0, 0); os.fchmod(output.fileno(), 0o444); os.fsync(output.fileno())
        if size != expected_size or digest.hexdigest() != expected_sha:
            os.unlink(temp, dir_fd=dirfd); os.fsync(dirfd); raise SystemExit(95)
        read_exact(temp, 0o444)
        os.replace(temp, leaf, src_dir_fd=dirfd, dst_dir_fd=dirfd)
        os.fsync(dirfd)
        read_exact(leaf, 0o444)
finally:
    os.close(dirfd)
"#;

// Publish one already-verified generation blob into a final guest path using a same-filesystem
// temp, file fsync, atomic replacement, directory fsync, and final no-follow verification.
const MAC_LIMA_POST_PM_ATOMIC_PUBLISH_SCRIPT_V1: &str = r#"import hashlib, os, stat, sys
source, target, expected_sha, mode_text, generation_key, replace_text = sys.argv[1:]
mode = int(mode_text, 8); replace = replace_text == 'replace'
if (not target.startswith('/') or '\x00' in target or '/..' in target
        or not generation_key or any(c not in '0123456789abcdef' for c in generation_key)):
    raise SystemExit(101)
parent, leaf = os.path.split(target)
parent_meta = os.lstat(parent)
if not stat.S_ISDIR(parent_meta.st_mode) or stat.S_ISLNK(parent_meta.st_mode):
    raise SystemExit(102)
dirfd = os.open(parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
def digest_fd(fd):
    os.lseek(fd, 0, os.SEEK_SET); digest = hashlib.sha256(); size = 0
    while True:
        block = os.read(fd, 1024 * 1024)
        if not block: break
        size += len(block); digest.update(block)
    return size, digest.hexdigest()
sourcefd = os.open(source, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
try:
    smeta = os.fstat(sourcefd)
    source_size, source_sha = digest_fd(sourcefd)
    if (not stat.S_ISREG(smeta.st_mode) or smeta.st_nlink != 1 or smeta.st_uid != 0
            or smeta.st_gid != 0 or stat.S_IMODE(smeta.st_mode) != 0o444 or source_sha != expected_sha):
        raise SystemExit(103)
    try:
        finalfd = os.open(leaf, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=dirfd)
    except FileNotFoundError:
        finalfd = None
    if finalfd is not None:
        try:
            meta = os.fstat(finalfd); size, digest = digest_fd(finalfd)
            if (stat.S_ISREG(meta.st_mode) and meta.st_nlink == 1 and meta.st_uid == 0
                    and meta.st_gid == 0 and stat.S_IMODE(meta.st_mode) == mode
                    and size == source_size and digest == expected_sha):
                os.fsync(finalfd); os.fsync(dirfd); raise SystemExit(0)
            if not replace:
                raise SystemExit(104)
        finally:
            os.close(finalfd)
    temp = f'.{leaf}.substrate-r3-{generation_key}.partial'
    try:
        tempfd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600, dir_fd=dirfd)
    except FileExistsError:
        stale = os.open(temp, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=dirfd)
        stale_meta = os.fstat(stale); os.close(stale)
        if not stat.S_ISREG(stale_meta.st_mode) or stale_meta.st_nlink != 1 or stale_meta.st_uid != 0 or stale_meta.st_gid != 0:
            raise SystemExit(105)
        os.unlink(temp, dir_fd=dirfd)
        tempfd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600, dir_fd=dirfd)
    os.lseek(sourcefd, 0, os.SEEK_SET)
    with os.fdopen(tempfd, 'wb', closefd=True) as output:
        while True:
            block = os.read(sourcefd, 1024 * 1024)
            if not block: break
            output.write(block)
        output.flush(); os.fchown(output.fileno(), 0, 0); os.fchmod(output.fileno(), mode); os.fsync(output.fileno())
    verifyfd = os.open(temp, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=dirfd)
    try:
        meta = os.fstat(verifyfd); size, digest = digest_fd(verifyfd)
        if (not stat.S_ISREG(meta.st_mode) or meta.st_nlink != 1 or meta.st_uid != 0 or meta.st_gid != 0
                or stat.S_IMODE(meta.st_mode) != mode or size != source_size or digest != expected_sha):
            raise SystemExit(106)
    finally:
        os.close(verifyfd)
    os.replace(temp, leaf, src_dir_fd=dirfd, dst_dir_fd=dirfd); os.fsync(dirfd)
    finalfd = os.open(leaf, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=dirfd)
    try:
        meta = os.fstat(finalfd); size, digest = digest_fd(finalfd)
        if (not stat.S_ISREG(meta.st_mode) or meta.st_nlink != 1 or meta.st_uid != 0 or meta.st_gid != 0
                or stat.S_IMODE(meta.st_mode) != mode or size != source_size or digest != expected_sha):
            raise SystemExit(107)
        os.fsync(finalfd)
    finally:
        os.close(finalfd)
    os.fsync(dirfd)
finally:
    os.close(sourcefd); os.close(dirfd)
"#;

// Freshly measure the fixed installed guest publisher executor through a no-follow descriptor.
// The host independently exact-joins this canonical observation to the signed manifest before it
// can create any R6 predecessor.
const MAC_LIMA_R6_INSTALLED_EXECUTOR_MEASURE_SCRIPT_V1: &str = r#"import hashlib, json, os, stat
path = '/usr/libexec/substrate/substrate-lifecycle-linux'
fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
try:
    meta = os.fstat(fd)
    if (not stat.S_ISREG(meta.st_mode) or meta.st_nlink != 1 or meta.st_uid != 0
            or meta.st_gid != 0 or stat.S_IMODE(meta.st_mode) != 0o755):
        raise SystemExit(111)
    digest = hashlib.sha256(); size = 0; header = b''
    while True:
        block = os.read(fd, 1024 * 1024)
        if not block: break
        if len(header) < 20: header += block[:20-len(header)]
        size += len(block); digest.update(block)
    if len(header) < 20 or header[:6] != b'\x7fELF\x02\x01' or header[18:20] != b'\xb7\x00':
        raise SystemExit(112)
    print(json.dumps({'architecture':'AArch64','object_format':'ELF','sha256':digest.hexdigest(),
        'size':size,'target_triple':'aarch64-unknown-linux-gnu'}, sort_keys=True,
        separators=(',', ':')))
finally:
    os.close(fd)
"#;

const MAC_LIMA_WORLD_SERVICE_READINESS_SCRIPT_V1: &str = r#"set -u
service_sha="$1"
socket_sha="$2"
principal="$3"
principal_uid="$4"
/usr/bin/test "$principal_uid" != 0 || exit 49
/usr/bin/test "$(/usr/bin/id -un 2>/dev/null)" = "$principal" || exit 49
/usr/bin/test "$(/usr/bin/id -u 2>/dev/null)" = "$principal_uid" || exit 49
fresh_principal=$(/usr/bin/printf '#%s' "$principal_uid") || exit 49
/usr/bin/test "$(/usr/bin/sudo -n -u "$fresh_principal" -- /usr/bin/id -un 2>/dev/null)" = "$principal" || exit 49
/usr/bin/test "$(/usr/bin/sudo -n -u "$fresh_principal" -- /usr/bin/id -u 2>/dev/null)" = "$principal_uid" || exit 49
fresh_groups=$(/usr/bin/sudo -n -u "$fresh_principal" -- /usr/bin/id -nG 2>/dev/null) || exit 49
case " $fresh_groups " in
  *" substrate "*) ;;
  *) exit 49 ;;
esac
service_observed=$(/usr/bin/sha256sum /etc/systemd/system/substrate-world-service.service 2>/dev/null | /usr/bin/awk '{print $1}') || exit 41
socket_observed=$(/usr/bin/sha256sum /etc/systemd/system/substrate-world-service.socket 2>/dev/null | /usr/bin/awk '{print $1}') || exit 41
/usr/bin/test "$service_observed" = "$service_sha" || exit 41
/usr/bin/test "$socket_observed" = "$socket_sha" || exit 41
/usr/bin/test "$(/usr/bin/systemctl is-enabled substrate-world-service.socket 2>/dev/null)" = enabled || exit 42
/usr/bin/test "$(/usr/bin/systemctl show -p FragmentPath --value substrate-world-service.socket 2>/dev/null)" = /etc/systemd/system/substrate-world-service.socket || exit 43
/usr/bin/test "$(/usr/bin/systemctl show -p FragmentPath --value substrate-world-service.service 2>/dev/null)" = /etc/systemd/system/substrate-world-service.service || exit 43
socket_state=$(/usr/bin/systemctl is-active substrate-world-service.socket 2>/dev/null || true)
service_state=$(/usr/bin/systemctl is-active substrate-world-service.service 2>/dev/null || true)
if /usr/bin/test "$socket_state" != active || /usr/bin/test "$service_state" != active; then
  case "$socket_state:$service_state" in
    active:inactive|inactive:active|inactive:inactive) ;;
    *) exit 44 ;;
  esac
  printf '%s\n' substrate-world-service-before-v1
  exit 20
fi
# Both units must already be active before the endpoint is touched. The readiness observer never
# demand-activates the service; the fixed Start effect owns socket+service convergence together.
code=$(/usr/bin/sudo -n -u "$fresh_principal" -- /usr/bin/curl --silent --show-error --max-time 5 --output /dev/null --write-out '%{http_code}' --unix-socket /run/substrate.sock http://localhost/v1/execute 2>/dev/null) || exit 45
/usr/bin/test "$code" = 405 || exit 45
/usr/bin/test "$(/usr/bin/systemctl is-active substrate-world-service.socket 2>/dev/null)" = active || exit 46
/usr/bin/test "$(/usr/bin/systemctl is-active substrate-world-service.service 2>/dev/null)" = active || exit 46
/usr/bin/test ! -L /run/substrate.sock || exit 47
/usr/bin/test -S /run/substrate.sock || exit 47
/usr/bin/test "$(/usr/bin/stat -c '%U:%G:%a' /run/substrate.sock 2>/dev/null)" = root:substrate:660 || exit 47
/usr/bin/test -d /run/substrate || exit 48
/usr/bin/test "$(/usr/bin/stat -c '%U:%G:%a' /run/substrate 2>/dev/null)" = root:substrate:750 || exit 48
printf '%s\n' substrate-world-service-ready-v1
"#;
const MAC_LIMA_ROOT_INPUT_MAX_BYTES_V1: u64 = 256 * 1024 * 1024;
const MAC_LIMA_CHILD_FD_SCAN_LIMIT_V1: libc::c_long = 1_048_576;
const MAC_LIMA_OWNERSHIP_MAX_ENTRIES_V1: usize = 100_000;
const MAC_LIMA_OWNERSHIP_MAX_DEPTH_V1: usize = 64;
const MAC_LIMA_STAGE_ONE_PROFILE_TEMPLATE_ALGORITHM_V1: &str =
    "substrate.mac-lima-stage-one-profile-template";
const MAC_LIMA_STAGE_ONE_PROFILE_TEMPLATE_VERSION_V1: u32 = 1;
const MAC_LIMA_STAGE_ONE_MARKER_PATH_V1: &str =
    "/var/lib/substrate/.substrate-lima-stage-one-marker.v1";
// The marker is deliberately root-private. Lima's default guest principal owns the control
// session, so only this one fixed read crosses sudo; the machine/account/UID/home observations
// remain bound to the non-root guest principal.
const MAC_LIMA_STAGE_ONE_OBSERVATION_COMMAND_V1: &str = "set -eu; /usr/bin/sudo -n /bin/cat /var/lib/substrate/.substrate-lima-stage-one-marker.v1; printf 'guest_machine_id=%s\\nguest_account=%s\\nguest_uid=%s\\nguest_home=%s\\n' \"$(cat /etc/machine-id)\" \"$(id -un)\" \"$(id -u)\" \"$(getent passwd \"$(id -un)\" | cut -d: -f6)\"";
// This deliberately contains only an attempt/capsule marker and fixed Lima profile constants.
// It neither stages project bytes nor installs packages, DNS, publisher, world, or forwarding
// components. Dynamic data are rendered by `render_mac_lima_stage_one_profile_v1` only after the
// signed Stage-1 authorization was derived from retained state.
const MAC_LIMA_STAGE_ONE_PROFILE_TEMPLATE_V1: &str = r#"arch: "aarch64"
minimumLimaVersion: "1.0.0"
images:
  - location: "https://cloud-images.ubuntu.com/releases/24.04/release/ubuntu-24.04-server-cloudimg-arm64.img"
    arch: "aarch64"
provision:
  - mode: system
    script: |
      umask 077
      mkdir -p /var/lib/substrate
      chown root:root /var/lib/substrate
      chmod 0700 /var/lib/substrate
      printf '%s\n' "__SUBSTRATE_STAGE_ONE_ATTEMPT_MARKER__" "__SUBSTRATE_STAGE_ONE_CAPSULE_MARKER__" > /var/lib/substrate/.substrate-lima-stage-one-marker.v1
      chmod 0600 /var/lib/substrate/.substrate-lima-stage-one-marker.v1
"#;

/// Fixed state projections owned by the designated macOS lifecycle publisher.
#[derive(Debug, Clone)]
pub struct MacManagedArtifactExecutorV1 {
    state_root: PathBuf,
    protected_state: PathBuf,
    pairing_root: PathBuf,
}

/// Fixed XPC service identity; its behavior is guarded by designated-requirement attestation.
#[derive(Debug, Clone)]
pub struct MacLifecyclePublisherServiceV1 {
    mach_service: &'static str,
}

/// Account-database identity used for every retained publisher-side `limactl` child. The IH
/// carrier binds account+UID; the local account database supplies the exact primary GID and home.
/// Every spawn re-resolves the same tuple before dropping root credentials.
#[derive(Debug, Clone, PartialEq, Eq)]
struct MacLimaPrincipalV1 {
    account: String,
    uid: libc::uid_t,
    gid: libc::gid_t,
    home: String,
}

/// Own a fixed retained `limactl shell` child until its exact frame protocol reaches a terminal
/// status.  Any decode/CAS/Drop boundary kills and reaps the child rather than leaving a guest
/// process able to continue after the host rejected its state transition.
#[cfg(target_os = "macos")]
struct R6RetainedLimaChildGuardV1 {
    child: Option<Child>,
    carrier: InstallBootstrapContextCarrierV1,
    principal: MacLimaPrincipalV1,
    lima_home: String,
}

#[cfg(target_os = "macos")]
impl R6RetainedLimaChildGuardV1 {
    fn new(
        child: Child,
        carrier: &InstallBootstrapContextCarrierV1,
        principal: &MacLimaPrincipalV1,
        lima_home: &str,
    ) -> Self {
        Self {
            child: Some(child),
            carrier: carrier.clone(),
            principal: principal.clone(),
            lima_home: lima_home.to_string(),
        }
    }

    fn finish(&mut self) -> Result<ExitStatus> {
        let child = self
            .child
            .as_mut()
            .ok_or_else(|| anyhow::anyhow!("R6 retained Lima child was already finalized"))?;
        let deadline = Instant::now() + R6_DATA_CHILD_EXIT_TIMEOUT_V1;
        loop {
            if let Some(status) = child
                .try_wait()
                .context("poll fixed retained R6 Lima child")?
            {
                // `try_wait` has reaped the child; dropping the now-empty guard must not kill a
                // reused PID. Keep ownership until this successful terminal observation.
                self.child.take();
                let post_validation = mac_validate_lima_after_command_v1(
                    &self.carrier,
                    &self.principal,
                    &self.lima_home,
                );
                return mac_join_r6_exit_status_and_post_validation_v1(status, post_validation);
            }
            if Instant::now() >= deadline {
                bail!("R6 data child exceeded its fixed terminal exit deadline");
            }
            std::thread::sleep(Duration::from_millis(20));
        }
    }
}

/// Preserve the R6 child's causal nonzero status when terminal Lima-state validation also
/// fails. The caller still receives an ordinary nonzero `ExitStatus` when validation succeeds,
/// so its existing closed-protocol error remains authoritative in that single-failure case.
#[cfg(target_os = "macos")]
fn mac_join_r6_exit_status_and_post_validation_v1(
    status: ExitStatus,
    post_validation: Result<()>,
) -> Result<ExitStatus> {
    match (status.success(), post_validation) {
        (_, Ok(())) => Ok(status),
        (true, Err(validation_error)) => Err(validation_error),
        (false, Err(validation_error)) => bail!(
            "fixed retained R6 Lima child exited nonzero ({:?}); post-command validation also failed: {validation_error:#}",
            status.code()
        ),
    }
}

#[cfg(target_os = "macos")]
impl std::ops::Deref for R6RetainedLimaChildGuardV1 {
    type Target = Child;

    fn deref(&self) -> &Self::Target {
        self.child
            .as_ref()
            .expect("R6 retained Lima child guard is live")
    }
}

#[cfg(target_os = "macos")]
impl std::ops::DerefMut for R6RetainedLimaChildGuardV1 {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.child
            .as_mut()
            .expect("R6 retained Lima child guard is live")
    }
}

#[cfg(target_os = "macos")]
impl Drop for R6RetainedLimaChildGuardV1 {
    fn drop(&mut self) {
        if let Some(mut child) = self.child.take() {
            let _ = child.kill();
            let _ = child.wait();
            let _ = mac_revalidate_lima_principal_v1(&self.carrier, &self.principal);
            let _ = mac_verify_lima_control_state_ownership_v1(&self.principal, &self.lima_home);
            let _ = mac_require_absent_lima_owner_overlays_v1(&self.principal, &self.lima_home);
        }
    }
}

fn main() -> Result<()> {
    let mut args = std::env::args();
    let _program = args.next();
    let operation = args
        .next()
        .ok_or_else(|| anyhow::anyhow!("missing macOS lifecycle operation"))?;
    if operation == "--publisher-bootstrap-fd" {
        if args.next().as_deref() != Some("3") || args.next().is_some() {
            bail!("publisher bootstrap accepts exactly --publisher-bootstrap-fd 3");
        }
        // This branch precedes all ordinary stdin handling.  Its sole input is the retained
        // SOCK_STREAM peer inherited at descriptor 3.
        return consume_publisher_bootstrap_fd3_v1(3);
    }
    if matches!(
        operation.as_str(),
        "--publisher-service-state-install-fd" | "--publisher-service-state-retire-fd"
    ) {
        if args.next().as_deref() != Some("3") || args.next().is_some() {
            bail!("publisher service-state operation accepts exactly retained descriptor 3");
        }
        mac_attest_closed_service_state_fd3_v1(3)?;
        let response = if operation == "--publisher-service-state-install-fd" {
            execute_closed_mac_publisher_service_state_install_v1()?
        } else {
            execute_closed_mac_publisher_service_state_retirement_v1()?
        };
        std::io::stdout()
            .write_all(&canonical_bootstrap_json_bytes_v1(&response)?)
            .context("write closed publisher service-state response")?;
        return Ok(());
    }
    if args.next().is_some() {
        bail!("macOS lifecycle operation has unexpected arguments");
    }
    if operation == "run-publisher" {
        // launchd invokes this operation without an untrusted stdin request. It must remain in
        // the fixed Mach-service listener rather than falling through to a one-shot stdio relay.
        let service = MacLifecyclePublisherServiceV1 {
            mach_service: MAC_MACH_SERVICE_V1,
        };
        return run_mac_xpc_publisher_v1(&service);
    }
    if operation == "guest-pairing-data-session" {
        bail!("R6 pairing protocol tags are available only through the attested XPC listener")
    }
    let mut input = Vec::new();
    std::io::stdin()
        .read_to_end(&mut input)
        .context("read macOS lifecycle executor input")?;
    let _executor = MacManagedArtifactExecutorV1 {
        state_root: PathBuf::from(MAC_STATE_ROOT_V1),
        protected_state: PathBuf::from(MAC_STATE_ROOT_V1).join("current-anchor.v1.json"),
        pairing_root: PathBuf::from(MAC_STATE_ROOT_V1).join("guest-pairings"),
    };
    let response = match operation.as_str() {
        // These are fixed XPC client relays only. They never run the action locally: the
        // launchd-owned listener below is the sole request handler and peer-attestation point.
        "stage-one-create" | "post-pm-action" | "prospective-retirement-v2" => {
            relay_mac_xpc_publisher_request_v1(operation.as_str(), &input)?
        }
        other => bail!("unknown macOS lifecycle operation {other}"),
    };
    std::io::stdout()
        .write_all(&serde_json::to_vec(&response).context("encode lifecycle response")?)
        .context("write macOS lifecycle executor response")?;
    Ok(())
}

#[cfg(target_os = "macos")]
fn mac_attest_closed_service_state_fd3_v1(fd: i32) -> Result<()> {
    use std::os::unix::net::UnixStream;

    if fd != 3 {
        bail!("publisher service-state peer must use descriptor 3");
    }
    mac_rearm_bootstrap_fd3_cloexec_v1(fd)?;
    mac_require_stream_channel_v1(fd)?;
    mac_set_bootstrap_no_sigpipe_v1(fd)?;
    // SAFETY: the closed service-state entrypoint takes sole ownership of verified FD3.
    let mut socket = unsafe { UnixStream::from_raw_fd(fd) };
    socket
        .set_read_timeout(Some(MAC_BOOTSTRAP_FRAME_FINISH_TIMEOUT_V1))
        .context("bound closed service-state peer EOF observation")?;
    let peer = mac_bootstrap_peer_identity_v1(socket.as_raw_fd())?;
    let provenance = mac_load_retained_bootstrap_provenance_v1()?;
    mac_attest_bootstrap_control_peer_predecode_v1(&peer, &provenance)?;
    let mut forbidden = [0_u8; 1];
    match socket.read(&mut forbidden) {
        Ok(0) => Ok(()),
        Ok(_) => bail!("publisher service-state peer sent forbidden caller data"),
        Err(error) => Err(error).context("observe closed publisher service-state peer EOF"),
    }
}

#[cfg(not(target_os = "macos"))]
fn mac_attest_closed_service_state_fd3_v1(_fd: i32) -> Result<()> {
    bail!("publisher service-state peer attestation is unavailable off macOS")
}

/// Consume exactly one bounded EOF-delimited direct-bootstrap document from the peer on FD3.
///
/// The native admission layer owns the SO_PEERCRED-equivalent peer/image/build/terminal joins;
/// this entrypoint deliberately has neither a stdin fallback nor a second-frame retry path.
fn consume_publisher_bootstrap_fd3_v1(fd: i32) -> Result<()> {
    #[cfg(target_os = "macos")]
    {
        use std::os::unix::net::UnixStream;

        initialize_mac_bootstrap_milestone_logger_v1();
        let milestones_started = Instant::now();
        emit_mac_bootstrap_milestone_v1(milestones_started, "executor.fd3.received");
        if fd != 3 {
            bail!("publisher bootstrap must use descriptor 3");
        }
        // Re-arm close-on-exec before socket inspection, peer/image/terminal work, JSON decode,
        // codesign, or any later child exec. Sudo cleared this flag only for its fixed FD3 handoff.
        mac_rearm_bootstrap_fd3_cloexec_v1(fd)?;
        mac_require_stream_channel_v1(fd)?;
        mac_set_bootstrap_no_sigpipe_v1(fd)?;
        // SAFETY: this entrypoint now takes sole ownership of the verified inherited FD3.
        let socket = unsafe { UnixStream::from_raw_fd(fd) };
        // This kernel observation precedes every untrusted authorization decode.
        let peer = mac_bootstrap_peer_identity_v1(socket.as_raw_fd())?;
        let provenance = mac_load_retained_bootstrap_provenance_v1()?;
        // The peer's kernel PID and its retained executable are admitted before any authority
        // bytes are decoded.  Decoded bytes can only further constrain this fixed record.
        mac_attest_bootstrap_control_peer_predecode_v1(&peer, &provenance)?;
        let frame = mac_read_single_stream_document_v1(
            &socket,
            Instant::now() + MAC_BOOTSTRAP_FRAME_FINISH_TIMEOUT_V1,
            "retained bootstrap FD3 authorization",
        )?;
        let fresh_authorization = parse_publisher_bootstrap_authorization_v1(&frame)
            .context("decode canonical direct bootstrap authorization")?;
        mac_attest_bootstrap_authorization_to_provenance_v1(&fresh_authorization, &provenance)?;
        mac_attest_running_executor_image_v1(&fresh_authorization, &provenance)?;
        emit_mac_bootstrap_milestone_v1(
            milestones_started,
            "executor.frame.provenance.peer.validation.complete",
        );
        // The FD3 authority remains one-shot.  A repeat direct command supplies only another
        // IH-derived authorization to reach this retained locator; the original complete
        // authorization is reconstructed in memory from fixed facts and never serialized.
        let (authorization, locator) =
            mac_open_or_allocate_bootstrap_attempt_locator_v1(&fresh_authorization, &provenance)?;
        emit_mac_bootstrap_milestone_v1(milestones_started, "executor.bootstrap_attempt.allocated");
        let response = if locator.terminal_state == "Completed" {
            mac_validate_completed_bootstrap_attempt_locator_joins_v1(&locator)?;
            let response = mac_decode_attempt_locator_response_v1(&locator)?;
            emit_mac_bootstrap_milestone_v1(milestones_started, "executor.locator.reread.complete");
            response
        } else {
            let response = bootstrap_mac_publisher_from_authorized_fd3_v1(
                &authorization,
                &provenance,
                milestones_started,
            )?;
            let _ = mac_complete_bootstrap_attempt_locator_v1(&locator, &authorization, &response)?;
            emit_mac_bootstrap_milestone_v1(
                milestones_started,
                "executor.locator.completion.complete",
            );
            response
        };
        let response = canonical_bootstrap_json_bytes_v1(&response)
            .context("encode bounded bootstrap response")?;
        let response_write_deadline = Instant::now() + MAC_BOOTSTRAP_FRAME_FINISH_TIMEOUT_V1;
        emit_mac_bootstrap_milestone_v1(
            milestones_started,
            "executor.response.serialization.complete",
        );
        emit_mac_bootstrap_milestone_v1(milestones_started, "executor.response.write.start");
        mac_send_single_stream_document_v1(
            &socket,
            &response,
            response_write_deadline,
            milestones_started,
        )
    }
    #[cfg(not(target_os = "macos"))]
    {
        let _ = fd;
        bail!("publisher bootstrap FD3 entrypoint is available only on macOS")
    }
}

fn mac_bootstrap_milestone_line_v1(milestone: &'static str, elapsed: Duration) -> String {
    format!(
        "{MAC_BOOTSTRAP_MILESTONE_PREFIX_V1}={milestone} elapsed_ms={}",
        elapsed.as_millis()
    )
}

#[cfg(target_os = "macos")]
const MAC_BOOTSTRAP_MILESTONE_QUEUE_CAPACITY_V1: usize = 32;

#[cfg(target_os = "macos")]
static MAC_BOOTSTRAP_MILESTONE_SENDER_V1: std::sync::OnceLock<std::sync::mpsc::SyncSender<String>> =
    std::sync::OnceLock::new();

/// Start the best-effort diagnostic writer before any direct-bootstrap phase deadline begins.
///
/// The worker is detached and never joined. A blocked stderr sink can stall only that worker;
/// protocol handling, response EOF, and process exit drop diagnostics instead of waiting.
#[cfg(target_os = "macos")]
fn initialize_mac_bootstrap_milestone_logger_v1() {
    if MAC_BOOTSTRAP_MILESTONE_SENDER_V1.get().is_some() {
        return;
    }
    let (sender, receiver) =
        std::sync::mpsc::sync_channel(MAC_BOOTSTRAP_MILESTONE_QUEUE_CAPACITY_V1);
    if std::thread::Builder::new()
        .name("substrate-bootstrap-stderr".to_string())
        .spawn(move || {
            run_mac_bootstrap_milestone_sink_v1(receiver, |line| {
                use std::io::Write as _;

                let _ = std::io::stderr().write_all(line.as_bytes());
            })
        })
        .is_ok()
    {
        let _ = MAC_BOOTSTRAP_MILESTONE_SENDER_V1.set(sender);
    }
}

#[cfg(target_os = "macos")]
fn run_mac_bootstrap_milestone_sink_v1(
    receiver: std::sync::mpsc::Receiver<String>,
    mut sink: impl FnMut(String),
) {
    while let Ok(line) = receiver.recv() {
        sink(line);
    }
}

#[cfg(target_os = "macos")]
fn try_enqueue_mac_bootstrap_milestone_v1(
    sender: &std::sync::mpsc::SyncSender<String>,
    line: String,
) {
    let _ = sender.try_send(line);
}

#[cfg(target_os = "macos")]
fn emit_mac_bootstrap_milestone_v1(started: Instant, milestone: &'static str) {
    if let Some(sender) = MAC_BOOTSTRAP_MILESTONE_SENDER_V1.get() {
        let mut line = mac_bootstrap_milestone_line_v1(milestone, started.elapsed());
        line.push('\n');
        try_enqueue_mac_bootstrap_milestone_v1(sender, line);
    }
}

#[cfg(not(target_os = "macos"))]
fn emit_mac_bootstrap_milestone_v1(started: Instant, milestone: &'static str) {
    let _ = (started, milestone);
}

#[cfg(target_os = "macos")]
#[derive(Debug, Clone, Copy)]
struct MacBootstrapPeerIdentityV1 {
    pid: libc::pid_t,
    uid: libc::uid_t,
    gid: libc::gid_t,
}

#[cfg(target_os = "macos")]
fn mac_rearm_bootstrap_fd3_cloexec_v1(fd: i32) -> Result<()> {
    let flags = unsafe { libc::fcntl(fd, libc::F_GETFD) };
    if flags < 0 {
        return Err(std::io::Error::last_os_error())
            .context("read retained bootstrap FD3 descriptor flags");
    }
    if unsafe { libc::fcntl(fd, libc::F_SETFD, flags | libc::FD_CLOEXEC) } != 0 {
        return Err(std::io::Error::last_os_error())
            .context("re-arm retained bootstrap FD3 CLOEXEC");
    }
    Ok(())
}

/// Refuse a datagram, seqpacket, replacement descriptor, or any transport other than the
/// one-shot Darwin AF_UNIX SOCK_STREAM channel.
#[cfg(target_os = "macos")]
fn mac_require_stream_channel_v1(fd: i32) -> Result<()> {
    let mut socket_type = 0_i32;
    let mut socket_type_len = std::mem::size_of::<i32>() as libc::socklen_t;
    // SAFETY: getsockopt writes exactly one integer into the supplied fixed-size buffer.
    if unsafe {
        libc::getsockopt(
            fd,
            libc::SOL_SOCKET,
            libc::SO_TYPE,
            (&mut socket_type as *mut i32).cast(),
            &mut socket_type_len,
        )
    } != 0
    {
        return Err(std::io::Error::last_os_error())
            .context("inspect retained bootstrap FD3 socket type");
    }
    if socket_type_len as usize != std::mem::size_of::<i32>() || socket_type != libc::SOCK_STREAM {
        bail!("retained bootstrap FD3 is not SOCK_STREAM");
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn mac_set_bootstrap_no_sigpipe_v1(fd: i32) -> Result<()> {
    let enabled = 1_i32;
    if unsafe {
        libc::setsockopt(
            fd,
            libc::SOL_SOCKET,
            libc::SO_NOSIGPIPE,
            (&enabled as *const i32).cast(),
            std::mem::size_of::<i32>() as libc::socklen_t,
        )
    } != 0
    {
        return Err(std::io::Error::last_os_error())
            .context("set retained bootstrap FD3 SO_NOSIGPIPE");
    }
    Ok(())
}

/// Obtain the direct peer from Darwin kernel credentials and prove it retains this controlling
/// terminal's session before an authorization payload is decoded.
#[cfg(target_os = "macos")]
fn mac_bootstrap_peer_identity_v1(fd: i32) -> Result<MacBootstrapPeerIdentityV1> {
    let mut uid = 0 as libc::uid_t;
    let mut gid = 0 as libc::gid_t;
    // SAFETY: getpeereid obtains AF_UNIX peer credentials from the kernel.
    if unsafe { libc::getpeereid(fd, &mut uid, &mut gid) } != 0 {
        return Err(std::io::Error::last_os_error())
            .context("read retained bootstrap FD3 peer credentials");
    }
    let mut pid = 0 as libc::pid_t;
    let mut pid_len = std::mem::size_of::<libc::pid_t>() as libc::socklen_t;
    // SAFETY: LOCAL_PEERPID returns the endpoint PID owned by the kernel, never JSON.
    if unsafe {
        libc::getsockopt(
            fd,
            libc::SOL_LOCAL,
            libc::LOCAL_PEERPID,
            (&mut pid as *mut libc::pid_t).cast(),
            &mut pid_len,
        )
    } != 0
    {
        return Err(std::io::Error::last_os_error())
            .context("read retained bootstrap FD3 peer PID");
    }
    if pid_len as usize != std::mem::size_of::<libc::pid_t>() || pid <= 1 {
        bail!("retained bootstrap FD3 has no kernel-owned peer PID");
    }
    let tty = fs::OpenOptions::new()
        .read(true)
        .open("/dev/tty")
        .context("open retained controlling terminal for bootstrap join")?;
    // SAFETY: these calls read kernel-owned session identifiers for retained descriptors/PIDs.
    let terminal_session = unsafe { libc::tcgetsid(tty.as_raw_fd()) };
    let peer_session = unsafe { libc::getsid(pid) };
    if terminal_session <= 0 || peer_session <= 0 || terminal_session != peer_session {
        bail!("retained bootstrap FD3 peer does not control the confirmed terminal session");
    }
    Ok(MacBootstrapPeerIdentityV1 { pid, uid, gid })
}

#[cfg(target_os = "macos")]
fn mac_wait_bootstrap_fd3_event_v1(
    fd: i32,
    events: i16,
    deadline: Instant,
    phase: &str,
) -> Result<()> {
    loop {
        let now = Instant::now();
        if now >= deadline {
            bail!("{phase} timed out");
        }
        let timeout_ms = deadline
            .saturating_duration_since(now)
            .as_millis()
            .saturating_add(1)
            .min(i32::MAX as u128) as i32;
        let mut poll_fd = libc::pollfd {
            fd,
            events,
            revents: 0,
        };
        let ready = unsafe { libc::poll(&mut poll_fd, 1, timeout_ms) };
        if ready == 0 {
            bail!("{phase} timed out");
        }
        if ready < 0 {
            let error = std::io::Error::last_os_error();
            if error.kind() == std::io::ErrorKind::Interrupted {
                continue;
            }
            return Err(error).with_context(|| format!("wait for {phase}"));
        }
        if poll_fd.revents & (libc::POLLNVAL | libc::POLLERR) != 0 {
            bail!("{phase} retained FD3 channel failed");
        }
        if poll_fd.revents & events != 0
            || (events == libc::POLLIN && poll_fd.revents & libc::POLLHUP != 0)
        {
            return Ok(());
        }
        if poll_fd.revents & libc::POLLHUP != 0 {
            bail!("{phase} retained FD3 channel disconnected");
        }
    }
}

#[cfg(target_os = "macos")]
fn mac_read_single_stream_document_v1(
    socket: &std::os::unix::net::UnixStream,
    deadline: Instant,
    phase: &str,
) -> Result<Vec<u8>> {
    let mut bytes = Vec::with_capacity(MAX_MAC_XPC_FRAME_BYTES_V1);
    let mut buffer = [0_u8; 16 * 1024];
    loop {
        mac_wait_bootstrap_fd3_event_v1(socket.as_raw_fd(), libc::POLLIN, deadline, phase)?;
        let remaining = MAX_MAC_XPC_FRAME_BYTES_V1 - bytes.len();
        let capacity = if remaining == 0 {
            1
        } else {
            remaining.min(buffer.len())
        };
        let count = unsafe {
            libc::recv(
                socket.as_raw_fd(),
                buffer.as_mut_ptr().cast(),
                capacity,
                libc::MSG_DONTWAIT,
            )
        };
        if count == 0 {
            if bytes.is_empty() {
                bail!("{phase} was empty");
            }
            return Ok(bytes);
        }
        if count > 0 {
            if remaining == 0 {
                bail!("{phase} exceeded the 1 MiB bound");
            }
            bytes.extend_from_slice(&buffer[..count as usize]);
            continue;
        }
        let error = std::io::Error::last_os_error();
        if matches!(
            error.kind(),
            std::io::ErrorKind::Interrupted | std::io::ErrorKind::WouldBlock
        ) {
            continue;
        }
        return Err(error).with_context(|| format!("read {phase}"));
    }
}

#[cfg(target_os = "macos")]
fn mac_send_single_stream_document_v1(
    socket: &std::os::unix::net::UnixStream,
    response: &[u8],
    deadline: Instant,
    milestones_started: Instant,
) -> Result<()> {
    if response.is_empty() || response.len() > MAX_MAC_XPC_FRAME_BYTES_V1 {
        bail!("retained bootstrap FD3 response is absent or oversized");
    }
    let mut written = 0usize;
    while written < response.len() {
        mac_wait_bootstrap_fd3_event_v1(
            socket.as_raw_fd(),
            libc::POLLOUT,
            deadline,
            "retained bootstrap FD3 response",
        )?;
        let count = unsafe {
            libc::send(
                socket.as_raw_fd(),
                response[written..].as_ptr().cast(),
                response.len() - written,
                libc::MSG_DONTWAIT,
            )
        };
        if count > 0 {
            written += count as usize;
            continue;
        }
        if count == 0 {
            bail!("retained bootstrap FD3 response made no forward progress");
        }
        let error = std::io::Error::last_os_error();
        if matches!(
            error.kind(),
            std::io::ErrorKind::Interrupted | std::io::ErrorKind::WouldBlock
        ) {
            continue;
        }
        return Err(error).context("send retained bootstrap FD3 response");
    }
    emit_mac_bootstrap_milestone_v1(milestones_started, "executor.response.write.end");
    // EOF is the sole response boundary and follows every canonical response byte.
    if unsafe { libc::shutdown(socket.as_raw_fd(), libc::SHUT_WR) } != 0 {
        return Err(std::io::Error::last_os_error())
            .context("finish retained bootstrap FD3 response");
    }
    emit_mac_bootstrap_milestone_v1(milestones_started, "executor.response.eof");
    Ok(())
}

#[cfg(target_os = "macos")]
fn mac_attest_bootstrap_control_peer_predecode_v1(
    peer: &MacBootstrapPeerIdentityV1,
    provenance: &MacPublisherInstallProvenanceV1,
) -> Result<()> {
    if peer.uid == 0 && peer.gid == 0 {
        bail!("retained bootstrap FD3 refuses a root-originated control peer");
    }
    let executable = mac_kernel_peer_executable_path_v1(peer.pid)?;
    let image = mac_measure_bootstrap_image_v1(&executable)?;
    let path_after = mac_kernel_peer_executable_path_v1(peer.pid)?;
    if executable != path_after
        || image.artifact_sha256 != provenance.control_image.artifact_sha256
        || image.artifact_identity != provenance.control_image.physical_identity
        || image.code_identity != provenance.control_image.code_identity
    {
        bail!("retained bootstrap FD3 peer image changed or does not join retained provenance");
    }
    mac_system_keychain_ffi_v1::verify_process_designated_requirement(
        peer.pid,
        &provenance.control_authority.designated_requirement,
    )
}

#[cfg(target_os = "macos")]
fn mac_attest_bootstrap_authorization_to_provenance_v1(
    authorization: &PublisherBootstrapAuthorizationV1,
    provenance: &MacPublisherInstallProvenanceV1,
) -> Result<()> {
    validate_publisher_bootstrap_authorization_v1(authorization)?;
    let authority = authorization
        .mac_control_authority
        .as_ref()
        .ok_or_else(|| anyhow::anyhow!("bootstrap authorization lacks mac control authority"))?;
    if *authority != provenance.control_authority
        || authorization.source_commit != provenance.source_commit
        || authorization.source_tree != provenance.source_tree
        || authorization.source_ref != provenance.source_ref
        || authorization.host_context_commitment != provenance.host_context_commitment
    {
        bail!("decoded bootstrap authority does not further constrain retained provenance");
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn mac_attest_running_executor_image_v1(
    authorization: &PublisherBootstrapAuthorizationV1,
    provenance: &MacPublisherInstallProvenanceV1,
) -> Result<()> {
    let evidence = &authorization.executor_build_evidence;
    if evidence.source_commit != authorization.source_commit
        || evidence.source_tree != authorization.source_tree
        || evidence.source_ref != authorization.source_ref
    {
        bail!("executor build evidence does not join bootstrap authorization source identity");
    }
    let path = std::env::current_exe().context("resolve fixed bootstrap executor image")?;
    let image = mac_measure_bootstrap_image_v1(&path)?;
    if image.artifact_sha256 != evidence.artifact_sha256
        || image.artifact_identity != evidence.artifact_identity
        || evidence.code_identity.as_deref() != Some(image.code_identity.as_str())
        || image.artifact_sha256 != provenance.executor_image.artifact_sha256
        || image.artifact_identity != provenance.executor_image.physical_identity
        || image.code_identity != provenance.executor_image.code_identity
    {
        bail!("running bootstrap executor image does not join published build evidence");
    }
    Ok(())
}

#[cfg(target_os = "macos")]
struct MacMeasuredBootstrapImageV1 {
    artifact_sha256: String,
    artifact_identity: String,
    code_identity: String,
}

#[cfg(target_os = "macos")]
fn mac_measure_bootstrap_image_v1(path: &Path) -> Result<MacMeasuredBootstrapImageV1> {
    let file = fs::OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(path)
        .with_context(|| {
            format!(
                "open bootstrap image without following links {}",
                path.display()
            )
        })?;
    let metadata = file
        .metadata()
        .with_context(|| format!("inspect bootstrap image {}", path.display()))?;
    if !metadata.file_type().is_file() || metadata.nlink() != 1 {
        bail!("bootstrap image must be one retained regular-file identity");
    }
    let mut reader = file;
    let mut digest = Sha256::new();
    let mut buffer = [0_u8; 64 * 1024];
    loop {
        let count = reader
            .read(&mut buffer)
            .context("hash retained bootstrap image")?;
        if count == 0 {
            break;
        }
        digest.update(&buffer[..count]);
    }
    let output = std::process::Command::new("/usr/bin/codesign")
        .arg("-d")
        .arg("-vvv")
        .arg("--")
        .arg(path)
        .output()
        .context("measure retained bootstrap image CodeDirectory identity")?;
    if !output.status.success() {
        bail!("retained bootstrap image CodeDirectory measurement failed");
    }
    let retained_after = reader
        .metadata()
        .context("reinspect retained bootstrap image descriptor")?;
    let path_after = fs::metadata(path)
        .with_context(|| format!("reinspect bootstrap image path {}", path.display()))?;
    if retained_after.dev() != metadata.dev()
        || retained_after.ino() != metadata.ino()
        || path_after.dev() != metadata.dev()
        || path_after.ino() != metadata.ino()
    {
        bail!("bootstrap image identity changed during retained hash/code measurement");
    }
    let diagnostics = String::from_utf8_lossy(&output.stderr);
    let cdhash = diagnostics
        .lines()
        .find_map(|line| line.strip_prefix("CDHash="))
        .filter(|value| {
            value.len() == 40
                && value
                    .bytes()
                    .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        })
        .ok_or_else(|| anyhow::anyhow!("retained bootstrap image has no canonical CDHash"))?;
    Ok(MacMeasuredBootstrapImageV1 {
        artifact_sha256: format!("{:x}", digest.finalize()),
        artifact_identity: format!("dev:{}:ino:{}", metadata.dev(), metadata.ino()),
        code_identity: format!("cdhash:{cdhash}"),
    })
}

/// The privileged Stage-1 effect may execute only a tool published below a root-owned,
/// non-writable, no-follow path chain.  Hashing the final regular file alone is not sufficient:
/// otherwise a caller-controlled parent can replace the pathname between measurement and spawn.
#[cfg(target_os = "macos")]
fn mac_require_root_owned_immutable_tool_path_v1(path: &Path) -> Result<()> {
    if !path.is_absolute() {
        bail!("retained limactl tool path is not absolute");
    }
    let mut current = PathBuf::from("/");
    let mut saw_regular_file = false;
    for component in path.components() {
        match component {
            std::path::Component::RootDir => continue,
            std::path::Component::Normal(segment) => current.push(segment),
            _ => bail!("retained limactl tool path is not a canonical absolute identity"),
        }
        let metadata = fs::symlink_metadata(&current).with_context(|| {
            format!(
                "inspect retained limactl path segment {}",
                current.display()
            )
        })?;
        if metadata.file_type().is_symlink() || metadata.uid() != 0 || metadata.mode() & 0o022 != 0
        {
            bail!("retained limactl path segment is not root-owned immutable no-follow state");
        }
        if current == path {
            if !metadata.file_type().is_file() || metadata.nlink() != 1 {
                bail!("retained limactl tool is not one root-owned regular-file identity");
            }
            saw_regular_file = true;
        } else if !metadata.is_dir() {
            bail!("retained limactl path parent is not a directory");
        }
    }
    if !saw_regular_file {
        bail!("retained limactl tool path has no regular-file terminal identity");
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn mac_measure_root_owned_immutable_lima_tool_v1(
    path: &Path,
) -> Result<MacMeasuredBootstrapImageV1> {
    mac_require_root_owned_immutable_tool_path_v1(path)?;
    let first = mac_measure_bootstrap_image_v1(path)?;
    mac_require_root_owned_immutable_tool_path_v1(path)?;
    let second = mac_measure_bootstrap_image_v1(path)?;
    if first.artifact_sha256 != second.artifact_sha256
        || first.artifact_identity != second.artifact_identity
        || first.code_identity != second.code_identity
    {
        bail!("retained limactl identity changed during no-follow measurement");
    }
    Ok(first)
}

/// Resolve the FD3 peer executable through Darwin's kernel process table rather than an
/// authorization field.  The caller re-observes this path after descriptor hashing to make a
/// peer exec/identity race preserving-first.
#[cfg(target_os = "macos")]
fn mac_kernel_peer_executable_path_v1(pid: libc::pid_t) -> Result<PathBuf> {
    // PROC_PIDPATHINFO_MAXSIZE is the Darwin ABI fixed 4096-byte path buffer. Keep the constant
    // local because older libc crate releases do not expose it on every supported SDK.
    let mut bytes = vec![0_u8; 4096];
    // SAFETY: proc_pidpath writes at most the fixed buffer length for the kernel-owned PID.
    let length = unsafe { proc_pidpath(pid, bytes.as_mut_ptr().cast(), bytes.len() as u32) };
    if length <= 0 || length as usize >= bytes.len() {
        return Err(std::io::Error::last_os_error())
            .context("resolve retained bootstrap FD3 peer executable from kernel PID");
    }
    bytes.truncate(length as usize);
    let path = std::ffi::OsString::from_vec(bytes);
    let path = PathBuf::from(path);
    if !path.is_absolute() {
        bail!("kernel peer executable path is not absolute");
    }
    Ok(path)
}

/// Read the fixed root-owned bootstrap provenance through a no-follow descriptor.  This is
/// intentionally duplicated at the privilege boundary so an untrusted FD3 frame is never used
/// to select the retained record.
#[cfg(target_os = "macos")]
fn mac_load_retained_bootstrap_provenance_v1() -> Result<MacPublisherInstallProvenanceV1> {
    let path = Path::new(MAC_BOOTSTRAP_PROVENANCE_PATH_V1);
    let parent = path
        .parent()
        .ok_or_else(|| anyhow::anyhow!("fixed bootstrap provenance has no parent"))?;
    let parent_metadata = fs::symlink_metadata(parent).with_context(|| {
        format!(
            "inspect fixed bootstrap provenance parent {}",
            parent.display()
        )
    })?;
    if !parent_metadata.is_dir()
        || parent_metadata.uid() != 0
        || parent_metadata.gid() != 0
        || parent_metadata.mode() & 0o022 != 0
    {
        bail!("fixed bootstrap provenance parent is not root-owned no-follow identity");
    }
    let mut file = fs::OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(path)
        .with_context(|| format!("open fixed bootstrap provenance {}", path.display()))?;
    let metadata = file
        .metadata()
        .context("inspect fixed bootstrap provenance")?;
    if !metadata.is_file()
        || metadata.nlink() != 1
        || metadata.uid() != 0
        || metadata.gid() != 0
        || metadata.mode() & 0o777 != 0o444
    {
        bail!("fixed bootstrap provenance is not root:wheel 0444 regular file");
    }
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes)
        .context("read fixed bootstrap provenance")?;
    let path_after =
        fs::symlink_metadata(path).context("reinspect fixed bootstrap provenance path")?;
    if path_after.dev() != metadata.dev() || path_after.ino() != metadata.ino() {
        bail!("fixed bootstrap provenance changed during descriptor read");
    }
    let provenance: MacPublisherInstallProvenanceV1 =
        serde_json::from_slice(&bytes).context("decode fixed bootstrap provenance")?;
    validate_mac_publisher_install_provenance_v1(&provenance)?;
    if canonical_mac_publisher_install_provenance_v1(&provenance)? != bytes {
        bail!("fixed bootstrap provenance is not canonical");
    }
    Ok(provenance)
}

fn canonical_bootstrap_json_bytes_v1(value: &Value) -> Result<Vec<u8>> {
    fn write_value(value: &Value, output: &mut String) -> Result<()> {
        match value {
            Value::Null => output.push_str("null"),
            Value::Bool(value) => output.push_str(if *value { "true" } else { "false" }),
            Value::Number(value) if value.is_i64() || value.is_u64() => {
                output.push_str(&value.to_string())
            }
            Value::Number(_) => bail!("bootstrap canonical JSON rejects non-integer number"),
            Value::String(value) => output.push_str(
                &serde_json::to_string(value).context("encode bootstrap canonical JSON string")?,
            ),
            Value::Array(values) => {
                output.push('[');
                for (index, value) in values.iter().enumerate() {
                    if index != 0 {
                        output.push(',');
                    }
                    write_value(value, output)?;
                }
                output.push(']');
            }
            Value::Object(values) => {
                let mut keys: Vec<_> = values.keys().collect();
                keys.sort_unstable();
                output.push('{');
                for (index, key) in keys.into_iter().enumerate() {
                    if index != 0 {
                        output.push(',');
                    }
                    output.push_str(
                        &serde_json::to_string(key)
                            .context("encode bootstrap canonical JSON object key")?,
                    );
                    output.push(':');
                    write_value(
                        values.get(key).ok_or_else(|| {
                            anyhow::anyhow!("bootstrap canonical JSON key vanished")
                        })?,
                        output,
                    )?;
                }
                output.push('}');
            }
        }
        Ok(())
    }

    let mut output = String::new();
    write_value(value, &mut output)?;
    Ok(output.into_bytes())
}

fn sha256_hex_bootstrap_v1(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

#[cfg(target_os = "macos")]
#[derive(Debug, Clone)]
struct MacPublisherInstalledArtifactsV1 {
    helper: MacPublisherServiceFileIdentityV1,
    plist: MacPublisherServiceFileIdentityV1,
    provenance: MacPublisherServiceFileIdentityV1,
    provenance_record: MacPublisherInstallProvenanceV1,
}

#[cfg(target_os = "macos")]
fn mac_require_service_state_root_v1() -> Result<()> {
    // SAFETY: geteuid has no preconditions and does not mutate process state.
    if unsafe { libc::geteuid() } != 0 {
        bail!("publisher service-state transition requires the privileged executor")
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn mac_fixed_path_exists_v1(path: &Path) -> Result<bool> {
    match fs::symlink_metadata(path) {
        Ok(_) => Ok(true),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(error).with_context(|| format!("inspect fixed path {}", path.display())),
    }
}

#[cfg(target_os = "macos")]
fn mac_measure_fixed_service_file_v1(
    path: &Path,
    required_mode: u32,
) -> Result<(MacPublisherServiceFileIdentityV1, Vec<u8>)> {
    mac_require_root_owned_immutable_tool_path_v1(path)?;
    let mut file = fs::OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW)
        .open(path)
        .with_context(|| format!("open fixed service file {}", path.display()))?;
    let metadata = file
        .metadata()
        .with_context(|| format!("inspect fixed service file {}", path.display()))?;
    if !metadata.file_type().is_file()
        || metadata.nlink() != 1
        || metadata.uid() != 0
        || metadata.gid() != 0
        || metadata.mode() & 0o777 != required_mode
    {
        bail!(
            "fixed service file is not exact root:wheel {:04o} state: {}",
            required_mode,
            path.display()
        );
    }
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes)
        .with_context(|| format!("read fixed service file {}", path.display()))?;
    let after = fs::symlink_metadata(path)
        .with_context(|| format!("reinspect fixed service file {}", path.display()))?;
    if after.dev() != metadata.dev()
        || after.ino() != metadata.ino()
        || after.uid() != metadata.uid()
        || after.gid() != metadata.gid()
        || after.mode() != metadata.mode()
    {
        bail!("fixed service file identity changed during measurement");
    }
    Ok((
        MacPublisherServiceFileIdentityV1 {
            path: path.display().to_string(),
            artifact_sha256: sha256_hex_bootstrap_v1(&bytes),
            physical_identity: format!("dev:{}:ino:{}", metadata.dev(), metadata.ino()),
            owner_uid: metadata.uid(),
            group_gid: metadata.gid(),
            mode: format!("{:04o}", metadata.mode() & 0o777),
            code_identity: None,
            code_requirement: None,
        },
        bytes,
    ))
}

#[cfg(target_os = "macos")]
fn mac_observe_publisher_service_files_v1() -> Result<(
    MacPublisherServiceFilesObservationV1,
    Option<MacPublisherInstalledArtifactsV1>,
)> {
    let helper_path = Path::new(MAC_PUBLISHER_HELPER_PATH_V1);
    let plist_path = Path::new(MAC_PUBLISHER_PLIST_PATH_V1);
    let provenance_path = Path::new(MAC_BOOTSTRAP_PROVENANCE_PATH_V1);
    let present = [
        mac_fixed_path_exists_v1(helper_path)?,
        mac_fixed_path_exists_v1(plist_path)?,
        mac_fixed_path_exists_v1(provenance_path)?,
    ];
    if present.iter().all(|value| !value) {
        return Ok((MacPublisherServiceFilesObservationV1::Absent, None));
    }
    if !present.iter().all(|value| *value) {
        return Ok((MacPublisherServiceFilesObservationV1::Ambiguous, None));
    }

    let (mut helper, _) = mac_measure_fixed_service_file_v1(helper_path, 0o755)?;
    let (plist, plist_bytes) = mac_measure_fixed_service_file_v1(plist_path, 0o644)?;
    let (provenance_identity, provenance_bytes) =
        mac_measure_fixed_service_file_v1(provenance_path, 0o444)?;
    let provenance_record: MacPublisherInstallProvenanceV1 =
        serde_json::from_slice(&provenance_bytes)
            .context("decode fixed publisher install provenance")?;
    validate_mac_publisher_install_provenance_v1(&provenance_record)?;
    if canonical_mac_publisher_install_provenance_v1(&provenance_record)? != provenance_bytes {
        bail!("fixed publisher install provenance is not canonical");
    }
    if plist_bytes != MAC_PUBLISHER_PLIST_BYTES_V1
        || plist.artifact_sha256 != provenance_record.launch_daemon_plist_sha256
    {
        bail!("fixed publisher plist does not exact-match the compiled installed artifact");
    }
    let measured_helper = mac_measure_bootstrap_image_v1(helper_path)?;
    if measured_helper.artifact_sha256 != helper.artifact_sha256
        || measured_helper.artifact_identity != helper.physical_identity
        || measured_helper.artifact_sha256 != provenance_record.executor_image.artifact_sha256
        || measured_helper.artifact_identity != provenance_record.executor_image.physical_identity
        || measured_helper.code_identity != provenance_record.executor_image.code_identity
    {
        bail!("fixed publisher helper does not exact-match install provenance");
    }
    let verification = Command::new("/usr/bin/codesign")
        .arg("--verify")
        .arg("--strict")
        .arg(format!(
            "-R={}",
            provenance_record.executor_image.code_requirement
        ))
        .arg("--")
        .arg(helper_path)
        .env_clear()
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .context("verify fixed publisher helper code requirement")?;
    if !verification.success() {
        bail!("fixed publisher helper fails its retained code requirement");
    }
    helper.code_identity = Some(measured_helper.code_identity);
    helper.code_requirement = Some(provenance_record.executor_image.code_requirement.clone());
    Ok((
        MacPublisherServiceFilesObservationV1::Exact,
        Some(MacPublisherInstalledArtifactsV1 {
            helper,
            plist,
            provenance: provenance_identity,
            provenance_record,
        }),
    ))
}

#[cfg(target_os = "macos")]
fn mac_classify_publisher_registration_exit_v1(
    status: &std::process::ExitStatus,
) -> MacPublisherServiceRegistrationObservationV1 {
    if status.success() {
        MacPublisherServiceRegistrationObservationV1::Registered
    } else if status.code() == Some(113) {
        MacPublisherServiceRegistrationObservationV1::Absent
    } else {
        MacPublisherServiceRegistrationObservationV1::Indeterminate
    }
}

#[cfg(target_os = "macos")]
fn mac_observe_publisher_registration_v1() -> MacPublisherServiceRegistrationObservationV1 {
    let domain = Command::new("/bin/launchctl")
        .arg("print")
        .arg("system")
        .env_clear()
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
    if !matches!(domain, Ok(status) if status.success()) {
        return MacPublisherServiceRegistrationObservationV1::Indeterminate;
    }
    match Command::new("/bin/launchctl")
        .arg("print")
        .arg(MAC_PUBLISHER_SERVICE_TARGET_V1)
        .env_clear()
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
    {
        Ok(status) => mac_classify_publisher_registration_exit_v1(&status),
        _ => MacPublisherServiceRegistrationObservationV1::Indeterminate,
    }
}

#[cfg(target_os = "macos")]
fn mac_publisher_service_state_account_v1(scope_id: &str) -> Result<String> {
    mac_keychain_account_v1(scope_id, MAC_PUBLISHER_SERVICE_STATE_ACCOUNT_SUFFIX_V1)
}

#[cfg(target_os = "macos")]
fn mac_read_publisher_service_state_record_v1(
    scope_id: &str,
) -> Result<Option<(MacPublisherServiceStateRecordV1, Vec<u8>)>> {
    let account = mac_publisher_service_state_account_v1(scope_id)?;
    let Some(bytes) = mac_keychain_read_item_v1(MAC_KEYCHAIN_SERVICE_V1, &account)? else {
        return Ok(None);
    };
    let record: MacPublisherServiceStateRecordV1 = serde_json::from_slice(&bytes)
        .context("decode protected publisher service-state record")?;
    if record.scope_id != scope_id
        || canonical_mac_publisher_service_state_record_v1(&record)? != bytes
    {
        bail!("protected publisher service-state record is not canonical for its fixed account");
    }
    Ok(Some((record, bytes)))
}

#[cfg(target_os = "macos")]
fn mac_cas_publisher_service_state_record_v1(
    scope_id: &str,
    expected: Option<&[u8]>,
    next: &MacPublisherServiceStateRecordV1,
) -> Result<Vec<u8>> {
    let account = mac_publisher_service_state_account_v1(scope_id)?;
    let observed = mac_keychain_read_item_v1(MAC_KEYCHAIN_SERVICE_V1, &account)?;
    if observed.as_deref() != expected {
        bail!("publisher service-state compare-and-swap conflict");
    }
    let bytes = canonical_mac_publisher_service_state_record_v1(next)?;
    mac_keychain_compare_and_swap_item_v1(MAC_KEYCHAIN_SERVICE_V1, &account, expected, &bytes)?;
    if mac_keychain_read_item_v1(MAC_KEYCHAIN_SERVICE_V1, &account)?.as_deref()
        != Some(bytes.as_slice())
    {
        bail!("publisher service-state CAS did not durably read back");
    }
    Ok(bytes)
}

#[cfg(target_os = "macos")]
fn mac_publisher_service_static_record_matches_v1(
    record: &MacPublisherServiceStateRecordV1,
    expected: &MacPublisherServiceStateRecordV1,
) -> bool {
    record.schema_owner == expected.schema_owner
        && record.schema_version == expected.schema_version
        && record.scope_id == expected.scope_id
        && record.bootstrap_authorization_sha256 == expected.bootstrap_authorization_sha256
        && record.bootstrap_intent_sha256 == expected.bootstrap_intent_sha256
        && record.initial_anchor_sha256 == expected.initial_anchor_sha256
        && record.protected_state_sha256 == expected.protected_state_sha256
        && record.stage_one_capsule_sha256 == expected.stage_one_capsule_sha256
        && record.install_provenance_sha256 == expected.install_provenance_sha256
        && record.bootstrap_attempt_locator_account == expected.bootstrap_attempt_locator_account
        && record.service_label == expected.service_label
        && record.launchd_domain == expected.launchd_domain
        && record.program_arguments == expected.program_arguments
        && record.mach_services == expected.mach_services
        && record.helper == expected.helper
        && record.plist == expected.plist
        && record.provenance == expected.provenance
}

#[cfg(target_os = "macos")]
fn mac_build_publisher_install_precommit_v1(
    admission: &MacPublisherControlAdmissionV1,
    state: &LifecyclePublisherProtectedStateV1,
    capsule: &MacLimaStageOneCapsuleV1,
    artifacts: &MacPublisherInstalledArtifactsV1,
) -> Result<MacPublisherServiceStateRecordV1> {
    let provenance_sha256 = sha256_hex_bootstrap_v1(
        &canonical_mac_publisher_install_provenance_v1(&artifacts.provenance_record)?,
    );
    if artifacts.provenance_record.control_authority != admission.control_authority
        || admission.bootstrap_authorization_sha256 != capsule.bootstrap_authorization_sha256
        || capsule.install_provenance_sha256 != provenance_sha256
        || capsule.scope_id != admission.scope_id
        || capsule.state != "Issued"
        || capsule.capsule_revision != 1
        || capsule.initial_anchor_counter != 0
        || capsule.initial_anchor_sha256 != admission.current_anchor_sha256
        || state.counter != 0
        || state.state_revision != admission.state_revision
        || state.prepared_record.is_some()
        || state.previous_protected_state_sha256.is_some()
        || lifecycle_anchor_sha256_v1(&state.current_anchor)? != admission.current_anchor_sha256
    {
        bail!("publisher service install does not exact-join signed Stage-1 bootstrap state");
    }
    if capsule.stage_one_authorization.expires_at_unix_ns <= mac_now_unix_ns_v1()? {
        bail!("publisher service install Stage-1 authority has expired");
    }
    let control_authority_sha256 =
        mac_publisher_control_authority_sha256_v1(&admission.control_authority)?;
    let executor_evidence_sha256 = sha256_hex_bootstrap_v1(&canonical_bootstrap_json_bytes_v1(
        &serde_json::to_value(
            &capsule
                .stage_one_authorization
                .successor_template
                .executor_build_evidence,
        )
        .context("encode retained Stage-1 executor evidence")?,
    )?);
    let key_spki_sha256 = sha256_hex_bootstrap_v1(&mac_open_system_keychain_p256_spki_der_v1(
        &admission.scope_id,
    )?);
    let intent = canonical_bootstrap_json_bytes_v1(&json!({
        "schema_owner": "substrate.mac-publisher-bootstrap-intent",
        "schema_version": 1,
        "scope_id": admission.scope_id,
        "authority_domain": state.current_anchor.authority_domain,
        "host_context_commitment": state.current_anchor.host_context_commitment,
        "platform_mapping_commitment": state.current_anchor.platform_mapping_commitment,
        "manifest_generation": admission.manifest_generation,
        "manifest_sha256": admission.manifest_sha256,
        "requester_principal": state.current_anchor.requester_principal,
        "attempt_nonce": state.current_anchor.attempt_nonce,
        "authorization_sha256": admission.bootstrap_authorization_sha256,
        "control_authority_sha256": control_authority_sha256,
        "executor_evidence_sha256": executor_evidence_sha256,
        "key_spki_sha256": key_spki_sha256,
        "state": "Completed",
    }))?;
    let intent_account = mac_keychain_bootstrap_intent_account_v1(&admission.scope_id)?;
    if mac_keychain_read_item_v1(MAC_KEYCHAIN_SERVICE_V1, &intent_account)?.as_deref()
        != Some(intent.as_slice())
    {
        bail!("publisher service install has no exact completed bootstrap intent");
    }
    Ok(MacPublisherServiceStateRecordV1 {
        schema_owner: "substrate.mac-publisher-service-state".to_string(),
        schema_version: 1,
        scope_id: admission.scope_id.clone(),
        bootstrap_authorization_sha256: admission.bootstrap_authorization_sha256.clone(),
        bootstrap_intent_sha256: sha256_hex_bootstrap_v1(&intent),
        initial_anchor_sha256: admission.current_anchor_sha256.clone(),
        protected_state_sha256: sha256_hex_bootstrap_v1(
            &canonical_lifecycle_publisher_protected_state_v1(state)?,
        ),
        stage_one_capsule_sha256: sha256_hex_bootstrap_v1(
            &canonical_mac_lima_stage_one_capsule_v1(capsule)?,
        ),
        install_provenance_sha256: provenance_sha256,
        bootstrap_attempt_locator_account: admission.bootstrap_attempt_locator_account.clone(),
        service_label: MAC_MACH_SERVICE_V1.to_string(),
        launchd_domain: "system".to_string(),
        program_arguments: vec![
            MAC_PUBLISHER_HELPER_PATH_V1.to_string(),
            "run-publisher".to_string(),
        ],
        mach_services: vec![MAC_MACH_SERVICE_V1.to_string()],
        helper: artifacts.helper.clone(),
        plist: artifacts.plist.clone(),
        provenance: artifacts.provenance.clone(),
        phase: MacPublisherServiceStatePhaseV1::InstallPrecommitted,
        registration_observed: false,
        files_observed_present: true,
        record_revision: 1,
        retirement_delete_cursor: 0,
        previous_record_sha256: None,
    })
}

#[cfg(target_os = "macos")]
fn mac_service_record_observation_v1(
    record: Option<&MacPublisherServiceStateRecordV1>,
    expected: Option<&MacPublisherServiceStateRecordV1>,
) -> MacPublisherServiceRecordObservationV1 {
    let Some(record) = record else {
        return if expected.is_some() {
            MacPublisherServiceRecordObservationV1::InstallIntentMatching
        } else {
            MacPublisherServiceRecordObservationV1::None
        };
    };
    if expected
        .is_some_and(|expected| !mac_publisher_service_static_record_matches_v1(record, expected))
    {
        return MacPublisherServiceRecordObservationV1::Mismatched;
    }
    match record.phase {
        MacPublisherServiceStatePhaseV1::InstallPrecommitted => {
            MacPublisherServiceRecordObservationV1::InstallPrecommittedMatching
        }
        MacPublisherServiceStatePhaseV1::Installed => {
            MacPublisherServiceRecordObservationV1::InstalledMatching
        }
        MacPublisherServiceStatePhaseV1::RetirementPrecommitted => {
            MacPublisherServiceRecordObservationV1::RetirementPrecommittedMatching
        }
        MacPublisherServiceStatePhaseV1::Retired => {
            MacPublisherServiceRecordObservationV1::RetiredMatching
        }
    }
}

#[cfg(target_os = "macos")]
fn mac_transition_publisher_service_record_v1(
    current: &MacPublisherServiceStateRecordV1,
    phase: MacPublisherServiceStatePhaseV1,
) -> Result<MacPublisherServiceStateRecordV1> {
    canonical_mac_publisher_service_state_record_v1(current)?;
    let transition_is_valid = matches!(
        (current.phase, current.retirement_delete_cursor, phase),
        (
            MacPublisherServiceStatePhaseV1::InstallPrecommitted,
            0,
            MacPublisherServiceStatePhaseV1::Installed
        ) | (
            MacPublisherServiceStatePhaseV1::Installed,
            0,
            MacPublisherServiceStatePhaseV1::RetirementPrecommitted
        ) | (
            MacPublisherServiceStatePhaseV1::RetirementPrecommitted,
            3,
            MacPublisherServiceStatePhaseV1::Retired
        )
    );
    if !transition_is_valid {
        bail!("publisher service-state phase transition is invalid");
    }
    let (registered, present) = match phase {
        MacPublisherServiceStatePhaseV1::Installed
        | MacPublisherServiceStatePhaseV1::RetirementPrecommitted => (true, true),
        MacPublisherServiceStatePhaseV1::Retired => (false, false),
        MacPublisherServiceStatePhaseV1::InstallPrecommitted => {
            bail!("publisher service-state cannot transition back to install precommit")
        }
    };
    Ok(MacPublisherServiceStateRecordV1 {
        phase,
        registration_observed: registered,
        files_observed_present: present,
        record_revision: current
            .record_revision
            .checked_add(1)
            .ok_or_else(|| anyhow::anyhow!("publisher service-state revision overflow"))?,
        previous_record_sha256: Some(mac_publisher_service_state_record_sha256_v1(current)?),
        ..current.clone()
    })
}

#[cfg(target_os = "macos")]
fn mac_service_state_response_v1(
    status: &str,
    record: &MacPublisherServiceStateRecordV1,
) -> Result<Value> {
    Ok(json!({
        "launchd_domain": "system",
        "record_sha256": mac_publisher_service_state_record_sha256_v1(record)?,
        "service_label": MAC_MACH_SERVICE_V1,
        "status": status,
    }))
}

#[cfg(target_os = "macos")]
fn mac_revalidate_publisher_service_record_authority_v1(
    admission: &MacPublisherControlAdmissionV1,
    record: &MacPublisherServiceStateRecordV1,
) -> Result<()> {
    if record.scope_id != admission.scope_id
        || record.bootstrap_authorization_sha256 != admission.bootstrap_authorization_sha256
        || record.bootstrap_attempt_locator_account != admission.bootstrap_attempt_locator_account
    {
        bail!("publisher service receipt does not join the current protected admission");
    }
    let locator = mac_read_bootstrap_attempt_locator_by_account_v1(
        &record.bootstrap_attempt_locator_account,
    )?;
    if locator.terminal_state != "Completed"
        || locator.scope_id != record.scope_id
        || locator.bootstrap_authorization_sha256 != record.bootstrap_authorization_sha256
        || locator.install_provenance_sha256 != record.install_provenance_sha256
        || locator.initial_anchor_sha256.as_deref() != Some(record.initial_anchor_sha256.as_str())
        || locator.protected_state_sha256.as_deref() != Some(record.protected_state_sha256.as_str())
        || locator.capsule_sha256.as_deref() != Some(record.stage_one_capsule_sha256.as_str())
    {
        bail!("publisher service receipt does not exact-join its completed bootstrap locator");
    }
    let capsule = open_mac_lima_stage_one_capsule_v1(&record.scope_id)?.ok_or_else(|| {
        anyhow::anyhow!("publisher service receipt has no retained Stage-1 capsule")
    })?;
    let initial_capsule = MacLimaStageOneCapsuleV1 {
        state: "Issued".to_string(),
        capsule_revision: 1,
        prepared_protected_state_sha256: None,
        rendered_profile_file_identity: None,
        observation: None,
        ..capsule.clone()
    };
    if sha256_hex_bootstrap_v1(&canonical_mac_lima_stage_one_capsule_v1(&initial_capsule)?)
        != record.stage_one_capsule_sha256
        || capsule.scope_id != record.scope_id
        || capsule.bootstrap_authorization_sha256 != record.bootstrap_authorization_sha256
        || capsule.install_provenance_sha256 != record.install_provenance_sha256
        || capsule.initial_anchor_sha256 != record.initial_anchor_sha256
        || capsule.pre_pm_manifest.manifest_sha256 != locator.pre_pm_manifest_sha256
        || capsule.stage_one_authorization.requester_principal != locator.requester_principal
        || capsule.stage_one_authorization.attempt_id != locator.attempt_id
        || capsule.stage_one_authorization.source_commit != locator.source_commit
        || capsule.stage_one_authorization.source_tree != locator.source_tree
        || capsule.stage_one_authorization.source_ref != locator.source_ref
    {
        bail!("publisher service retained Stage-1 capsule does not reconstruct its signed initial state");
    }
    let intent_account = mac_keychain_bootstrap_intent_account_v1(&record.scope_id)?;
    let intent =
        mac_keychain_read_item_v1(MAC_KEYCHAIN_SERVICE_V1, &intent_account)?.ok_or_else(|| {
            anyhow::anyhow!("publisher service receipt has no retained bootstrap intent")
        })?;
    let control_authority_sha256 =
        mac_publisher_control_authority_sha256_v1(&admission.control_authority)?;
    let executor_evidence_sha256 =
        sha256_hex_bootstrap_v1(&canonical_bootstrap_json_bytes_v1(&serde_json::to_value(
            &capsule
                .stage_one_authorization
                .successor_template
                .executor_build_evidence,
        )?)?);
    let key_spki_sha256 = sha256_hex_bootstrap_v1(&mac_open_system_keychain_p256_spki_der_v1(
        &record.scope_id,
    )?);
    let expected_intent = canonical_bootstrap_json_bytes_v1(&json!({
        "schema_owner": "substrate.mac-publisher-bootstrap-intent",
        "schema_version": 1,
        "scope_id": record.scope_id,
        "authority_domain": locator.authority_domain,
        "host_context_commitment": locator.host_context_commitment,
        "platform_mapping_commitment": capsule.pre_pm_manifest.platform_mapping_commitment,
        "manifest_generation": capsule.pre_pm_manifest.manifest_generation,
        "manifest_sha256": capsule.pre_pm_manifest.manifest_sha256,
        "requester_principal": locator.requester_principal,
        "attempt_nonce": locator.attempt_id,
        "authorization_sha256": record.bootstrap_authorization_sha256,
        "control_authority_sha256": control_authority_sha256,
        "executor_evidence_sha256": executor_evidence_sha256,
        "key_spki_sha256": key_spki_sha256,
        "state": "Completed",
    }))?;
    if intent != expected_intent
        || sha256_hex_bootstrap_v1(&intent) != record.bootstrap_intent_sha256
    {
        bail!("publisher service receipt does not exact-join its completed bootstrap intent");
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn mac_launchctl_bootstrap_publisher_v1() -> Result<std::process::ExitStatus> {
    Command::new("/bin/launchctl")
        .arg("bootstrap")
        .arg("system")
        .arg(MAC_PUBLISHER_PLIST_PATH_V1)
        .env_clear()
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .context("execute fixed system-domain publisher bootstrap")
}

#[cfg(target_os = "macos")]
fn execute_closed_mac_publisher_service_state_install_v1() -> Result<Value> {
    mac_require_service_state_root_v1()?;
    let admission = mac_verified_control_admission_v1()?;
    let (files, artifacts) = mac_observe_publisher_service_files_v1()?;
    let artifacts = artifacts
        .as_ref()
        .ok_or_else(|| anyhow::anyhow!("publisher service install fixed files are not exact"))?;
    let account = mac_publisher_service_state_account_v1(&admission.scope_id)?;
    let _guard = mac_keychain_durable_cas_guard_v1(&account)?;
    let observed = mac_read_publisher_service_state_record_v1(&admission.scope_id)?;
    let registration = mac_observe_publisher_registration_v1();
    if let Some((record, _)) = &observed {
        mac_revalidate_publisher_service_record_authority_v1(&admission, record)?;
        let provenance_sha256 = sha256_hex_bootstrap_v1(
            &canonical_mac_publisher_install_provenance_v1(&artifacts.provenance_record)?,
        );
        if record.bootstrap_authorization_sha256 != admission.bootstrap_authorization_sha256
            || record.helper != artifacts.helper
            || record.plist != artifacts.plist
            || record.provenance != artifacts.provenance
            || record.install_provenance_sha256 != provenance_sha256
        {
            bail!("publisher service receipt does not exact-join retained files and authority");
        }
        let retained_observation = mac_service_record_observation_v1(Some(record), None);
        match classify_mac_publisher_service_install_v1(registration, files, retained_observation) {
            MacPublisherServiceInstallDecisionV1::IdempotentSuccess => {
                return mac_service_state_response_v1("installed", record)
            }
            MacPublisherServiceInstallDecisionV1::BootstrapFromPrecommit => {}
            _ => {
                bail!(
                    "publisher service retained receipt is preserving-blocked: registration={registration:?} files={files:?} record={retained_observation:?}"
                )
            }
        }
    } else if registration != MacPublisherServiceRegistrationObservationV1::Absent {
        bail!("publisher service without a receipt is not definitely absent: {registration:?}");
    }

    let state = open_system_keychain_protected_state_for_scope_v1(&admission.scope_id)?
        .ok_or_else(|| anyhow::anyhow!("publisher service install has no protected state"))?;
    let capsule = open_mac_lima_stage_one_capsule_v1(&admission.scope_id)?
        .ok_or_else(|| anyhow::anyhow!("publisher service install has no Stage-1 capsule"))?;
    let expected =
        mac_build_publisher_install_precommit_v1(&admission, &state, &capsule, artifacts)?;
    let record_observation =
        mac_service_record_observation_v1(observed.as_ref().map(|value| &value.0), Some(&expected));
    let decision =
        classify_mac_publisher_service_install_v1(registration, files, record_observation);
    let precommit = match decision {
        MacPublisherServiceInstallDecisionV1::PrecommitAndBootstrap => {
            mac_cas_publisher_service_state_record_v1(&admission.scope_id, None, &expected)?;
            expected
        }
        MacPublisherServiceInstallDecisionV1::BootstrapFromPrecommit => observed
            .as_ref()
            .ok_or_else(|| anyhow::anyhow!("publisher service precommit disappeared"))?
            .0
            .clone(),
        MacPublisherServiceInstallDecisionV1::IdempotentSuccess => {
            return mac_service_state_response_v1(
                "installed",
                &observed
                    .as_ref()
                    .ok_or_else(|| anyhow::anyhow!("publisher service receipt disappeared"))?
                    .0,
            )
        }
        MacPublisherServiceInstallDecisionV1::PreserveAndStop => {
            bail!(
                "publisher service install prestate is preserving-blocked: registration={registration:?} files={files:?} record={record_observation:?}"
            )
        }
    };

    let (rechecked_files, rechecked_artifacts) = mac_observe_publisher_service_files_v1()?;
    if rechecked_files != MacPublisherServiceFilesObservationV1::Exact
        || rechecked_artifacts.as_ref().is_none_or(|value| {
            value.helper != precommit.helper
                || value.plist != precommit.plist
                || value.provenance != precommit.provenance
        })
    {
        bail!("publisher service fixed files changed after precommit");
    }
    let effect = mac_launchctl_bootstrap_publisher_v1()?;
    let registration_after = mac_observe_publisher_registration_v1();
    if !effect.success()
        || registration_after != MacPublisherServiceRegistrationObservationV1::Registered
    {
        bail!(
            "publisher service bootstrap did not reach a committable observation; preserving precommit: exit={effect:?} registration={registration_after:?}"
        );
    }
    let (files_after, artifacts_after) = mac_observe_publisher_service_files_v1()?;
    if files_after != MacPublisherServiceFilesObservationV1::Exact
        || artifacts_after.as_ref().is_none_or(|value| {
            value.helper != precommit.helper
                || value.plist != precommit.plist
                || value.provenance != precommit.provenance
        })
    {
        bail!("publisher service files changed after observed bootstrap effect");
    }
    let installed = mac_transition_publisher_service_record_v1(
        &precommit,
        MacPublisherServiceStatePhaseV1::Installed,
    )?;
    let precommit_bytes = canonical_mac_publisher_service_state_record_v1(&precommit)?;
    mac_cas_publisher_service_state_record_v1(
        &admission.scope_id,
        Some(&precommit_bytes),
        &installed,
    )?;
    mac_service_state_response_v1("installed", &installed)
}

#[cfg(target_os = "macos")]
fn mac_launchctl_bootout_publisher_v1() -> Result<std::process::ExitStatus> {
    Command::new("/bin/launchctl")
        .arg("bootout")
        .arg(MAC_PUBLISHER_SERVICE_TARGET_V1)
        .env_clear()
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .context("execute fixed system-domain publisher bootout")
}

#[cfg(target_os = "macos")]
fn mac_revalidate_publisher_retirement_files_v1(
    record: &MacPublisherServiceStateRecordV1,
) -> Result<[bool; 3]> {
    canonical_mac_publisher_service_state_record_v1(record)?;
    if record.phase != MacPublisherServiceStatePhaseV1::RetirementPrecommitted {
        bail!("publisher service file retirement lacks its protected precommit");
    }
    let paths = [
        Path::new(MAC_PUBLISHER_PLIST_PATH_V1),
        Path::new(MAC_PUBLISHER_HELPER_PATH_V1),
        Path::new(MAC_BOOTSTRAP_PROVENANCE_PATH_V1),
    ];
    let mut present = [false; 3];
    for (index, path) in paths.iter().enumerate() {
        present[index] = mac_fixed_path_exists_v1(path)?;
        if !present[index] {
            if index >= usize::from(record.retirement_delete_cursor) {
                bail!(
                    "publisher service retirement found an absent file before protected deletion authorization: {}",
                    path.display()
                );
            }
            continue;
        }
        match index {
            0 => {
                let (identity, bytes) = mac_measure_fixed_service_file_v1(path, 0o644)?;
                if identity != record.plist || bytes != MAC_PUBLISHER_PLIST_BYTES_V1 {
                    bail!("publisher service retirement refuses a mismatched fixed plist");
                }
            }
            1 => {
                let (mut identity, _) = mac_measure_fixed_service_file_v1(path, 0o755)?;
                let measured = mac_measure_bootstrap_image_v1(path)?;
                identity.code_identity = Some(measured.code_identity);
                identity.code_requirement = record.helper.code_requirement.clone();
                if measured.artifact_sha256 != identity.artifact_sha256
                    || measured.artifact_identity != identity.physical_identity
                    || identity != record.helper
                {
                    bail!("publisher service retirement refuses a mismatched fixed helper");
                }
                let requirement = record.helper.code_requirement.as_ref().ok_or_else(|| {
                    anyhow::anyhow!("publisher service receipt has no helper code requirement")
                })?;
                let verification = Command::new("/usr/bin/codesign")
                    .arg("--verify")
                    .arg("--strict")
                    .arg(format!("-R={requirement}"))
                    .arg("--")
                    .arg(path)
                    .env_clear()
                    .stdin(Stdio::null())
                    .stdout(Stdio::null())
                    .stderr(Stdio::null())
                    .status()
                    .context("reverify receipted publisher helper code requirement")?;
                if !verification.success() {
                    bail!(
                        "publisher service retirement helper fails its receipted code requirement"
                    );
                }
            }
            2 => {
                let (identity, bytes) = mac_measure_fixed_service_file_v1(path, 0o444)?;
                let provenance: MacPublisherInstallProvenanceV1 = serde_json::from_slice(&bytes)
                    .context("decode receipted install provenance")?;
                validate_mac_publisher_install_provenance_v1(&provenance)?;
                let canonical = canonical_mac_publisher_install_provenance_v1(&provenance)?;
                if identity != record.provenance
                    || canonical != bytes
                    || sha256_hex_bootstrap_v1(&canonical) != record.install_provenance_sha256
                    || provenance.launch_daemon_plist_sha256 != record.plist.artifact_sha256
                    || provenance.executor_image.artifact_sha256 != record.helper.artifact_sha256
                    || provenance.executor_image.physical_identity
                        != record.helper.physical_identity
                    || Some(&provenance.executor_image.code_identity)
                        != record.helper.code_identity.as_ref()
                    || Some(&provenance.executor_image.code_requirement)
                        != record.helper.code_requirement.as_ref()
                {
                    bail!("publisher service retirement refuses mismatched install provenance");
                }
            }
            _ => unreachable!("fixed publisher retirement path index"),
        }
    }
    Ok(present)
}

#[cfg(target_os = "macos")]
fn mac_advance_publisher_retirement_cursor_v1(
    current: &MacPublisherServiceStateRecordV1,
) -> Result<MacPublisherServiceStateRecordV1> {
    canonical_mac_publisher_service_state_record_v1(current)?;
    if current.phase != MacPublisherServiceStatePhaseV1::RetirementPrecommitted
        || current.retirement_delete_cursor >= 3
    {
        bail!("publisher service retirement cursor cannot advance");
    }
    Ok(MacPublisherServiceStateRecordV1 {
        record_revision: current
            .record_revision
            .checked_add(1)
            .ok_or_else(|| anyhow::anyhow!("publisher service-state revision overflow"))?,
        retirement_delete_cursor: current.retirement_delete_cursor + 1,
        previous_record_sha256: Some(mac_publisher_service_state_record_sha256_v1(current)?),
        ..current.clone()
    })
}

#[cfg(target_os = "macos")]
fn mac_resume_exact_publisher_service_file_retirement_v1(
    scope_id: &str,
    current: &mut MacPublisherServiceStateRecordV1,
    record_bytes: &mut Vec<u8>,
) -> Result<()> {
    let paths = [
        MAC_PUBLISHER_PLIST_PATH_V1,
        MAC_PUBLISHER_HELPER_PATH_V1,
        MAC_BOOTSTRAP_PROVENANCE_PATH_V1,
    ];
    for (index, path) in paths.iter().enumerate() {
        mac_revalidate_publisher_retirement_files_v1(current)?;
        if usize::from(current.retirement_delete_cursor) == index {
            let next = mac_advance_publisher_retirement_cursor_v1(current)?;
            *record_bytes = mac_cas_publisher_service_state_record_v1(
                scope_id,
                Some(record_bytes.as_slice()),
                &next,
            )?;
            *current = next;
        } else if usize::from(current.retirement_delete_cursor) < index {
            bail!("publisher service retirement cursor skipped a fixed path");
        }
        let rechecked = mac_revalidate_publisher_retirement_files_v1(current)?;
        if rechecked[index] {
            fs::remove_file(path).with_context(|| format!("remove exact receipted file {path}"))?;
            let parent = Path::new(path)
                .parent()
                .ok_or_else(|| anyhow::anyhow!("fixed receipted file has no parent"))?;
            fs::File::open(parent)
                .with_context(|| format!("open receipted file parent {}", parent.display()))?
                .sync_all()
                .with_context(|| format!("sync receipted file parent {}", parent.display()))?;
        }
    }
    if current.retirement_delete_cursor != 3
        || mac_revalidate_publisher_retirement_files_v1(current)? != [false; 3]
    {
        bail!("publisher service retirement did not prove all receipted files absent");
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn execute_closed_mac_publisher_service_state_retirement_v1() -> Result<Value> {
    mac_require_service_state_root_v1()?;
    let admission = mac_verified_control_admission_v1()?;
    let account = mac_publisher_service_state_account_v1(&admission.scope_id)?;
    let _guard = mac_keychain_durable_cas_guard_v1(&account)?;
    let observed = mac_read_publisher_service_state_record_v1(&admission.scope_id)?;
    let (record, mut record_bytes) = observed
        .ok_or_else(|| anyhow::anyhow!("publisher service retirement has no committed receipt"))?;
    if record.bootstrap_authorization_sha256 != admission.bootstrap_authorization_sha256 {
        bail!("publisher service retirement receipt does not join retained authority");
    }
    mac_revalidate_publisher_service_record_authority_v1(&admission, &record)?;
    let (files, artifacts) = mac_observe_publisher_service_files_v1()?;
    let record_observation = match files {
        MacPublisherServiceFilesObservationV1::Exact => {
            let artifacts = artifacts.as_ref().ok_or_else(|| {
                anyhow::anyhow!("publisher service exact file observation lost identities")
            })?;
            if artifacts.helper != record.helper
                || artifacts.plist != record.plist
                || artifacts.provenance != record.provenance
                || sha256_hex_bootstrap_v1(&canonical_mac_publisher_install_provenance_v1(
                    &artifacts.provenance_record,
                )?) != record.install_provenance_sha256
            {
                MacPublisherServiceRecordObservationV1::Mismatched
            } else {
                mac_service_record_observation_v1(Some(&record), None)
            }
        }
        _ => mac_service_record_observation_v1(Some(&record), None),
    };
    let registration = mac_observe_publisher_registration_v1();
    let decision = if record.phase == MacPublisherServiceStatePhaseV1::RetirementPrecommitted
        && registration == MacPublisherServiceRegistrationObservationV1::Absent
    {
        MacPublisherServiceRetirementDecisionV1::DeleteExactFiles
    } else if record.phase == MacPublisherServiceStatePhaseV1::RetirementPrecommitted
        && record.retirement_delete_cursor != 0
    {
        MacPublisherServiceRetirementDecisionV1::PreserveAndStop
    } else {
        classify_mac_publisher_service_retirement_v1(registration, files, record_observation)
    };
    let mut current = record;
    match decision {
        MacPublisherServiceRetirementDecisionV1::PrecommitAndBootout => {
            let next = mac_transition_publisher_service_record_v1(
                &current,
                MacPublisherServiceStatePhaseV1::RetirementPrecommitted,
            )?;
            record_bytes = mac_cas_publisher_service_state_record_v1(
                &admission.scope_id,
                Some(&record_bytes),
                &next,
            )?;
            current = next;
            let effect = mac_launchctl_bootout_publisher_v1()?;
            if !effect.success() {
                bail!(
                    "publisher service bootout failed; preserving retirement precommit: {effect:?}"
                );
            }
        }
        MacPublisherServiceRetirementDecisionV1::BootoutFromPrecommit => {
            let effect = mac_launchctl_bootout_publisher_v1()?;
            if !effect.success() {
                bail!(
                    "publisher service bootout failed; preserving retirement precommit: {effect:?}"
                );
            }
        }
        MacPublisherServiceRetirementDecisionV1::DeleteExactFiles
        | MacPublisherServiceRetirementDecisionV1::CommitRetired => {}
        MacPublisherServiceRetirementDecisionV1::IdempotentSuccess => {
            return mac_service_state_response_v1("retired", &current)
        }
        MacPublisherServiceRetirementDecisionV1::PreserveAndStop => {
            bail!(
                "publisher service retirement prestate is preserving-blocked: registration={registration:?} files={files:?} record={record_observation:?}"
            )
        }
    }

    let registration_after = mac_observe_publisher_registration_v1();
    if registration_after != MacPublisherServiceRegistrationObservationV1::Absent {
        bail!(
            "publisher service bootout has no definite absent observation: {registration_after:?}"
        );
    }
    mac_resume_exact_publisher_service_file_retirement_v1(
        &admission.scope_id,
        &mut current,
        &mut record_bytes,
    )?;
    let (files_final, _) = mac_observe_publisher_service_files_v1()?;
    if files_final != MacPublisherServiceFilesObservationV1::Absent
        || mac_observe_publisher_registration_v1()
            != MacPublisherServiceRegistrationObservationV1::Absent
    {
        bail!("publisher service retirement final absence proof failed");
    }
    let retired = mac_transition_publisher_service_record_v1(
        &current,
        MacPublisherServiceStatePhaseV1::Retired,
    )?;
    mac_cas_publisher_service_state_record_v1(&admission.scope_id, Some(&record_bytes), &retired)?;
    mac_service_state_response_v1("retired", &retired)
}

