    #[cfg(target_os = "macos")]
    #[test]
    fn xpc_missing_service_child_reports_connection_invalid_without_sigtrap() {
        const CHILD_ENV: &str = "SUBSTRATE_XPC_HANDLER_REGRESSION_CHILD_V1";
        const TEST_NAME: &str =
            "tests::xpc_missing_service_child_reports_connection_invalid_without_sigtrap";

        if std::env::var_os(CHILD_ENV).is_some() {
            let unique_service = format!(
                "com.substrate.xpc-handler-regression.{}.{}",
                std::process::id(),
                SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .expect("system clock after UNIX epoch")
                    .as_nanos()
            );
            let service = std::ffi::CString::new(unique_service)
                .expect("unique missing-service XPC probe name has no NUL");
            assert_eq!(
                unsafe { probe_unprivileged_missing_xpc_service_v1(&service) }
                    .expect("missing unprivileged service returns a structured XPC error"),
                MacXpcMissingServiceProbeV1::ConnectionInvalid
            );
            return;
        }

        let mut child =
            Command::new(std::env::current_exe().expect("resolve lifecycle test binary"))
                .args(["--exact", TEST_NAME, "--nocapture"])
                .env(CHILD_ENV, "1")
                .spawn()
                .expect("spawn isolated XPC handler regression child");
        let deadline = Instant::now() + Duration::from_secs(5);
        let status = loop {
            if let Some(status) = child.try_wait().expect("poll XPC handler regression child") {
                break status;
            }
            if Instant::now() >= deadline {
                child
                    .kill()
                    .expect("stop timed-out XPC handler regression child");
                let _ = child.wait();
                panic!("XPC handler regression child timed out");
            }
            std::thread::sleep(Duration::from_millis(10));
        };
        assert!(
            status.success(),
            "XPC handler regression child terminated abnormally: {status}"
        );
    }

    #[test]
    fn mac_xpc_relay_reply_classifier_is_fail_closed_and_bounded() {
        const MAX_FRAME_BYTES: usize = 8;
        use MacXpcReplyClassificationV1 as Classification;
        use MacXpcReplyDataV1 as Data;
        use MacXpcReplyObjectV1 as Object;

        for (object, data, expected) in [
            (
                Object::ConnectionInvalid,
                Data::Missing,
                Classification::ConnectionInvalid,
            ),
            (
                Object::ConnectionInterrupted,
                Data::Missing,
                Classification::ConnectionInterrupted,
            ),
            (
                Object::PeerCodeSigningRequirementRejected,
                Data::Missing,
                Classification::PeerCodeSigningRequirementRejected,
            ),
            (
                Object::UnexpectedXpcType,
                Data::Missing,
                Classification::UnexpectedXpcType,
            ),
            (
                Object::Dictionary,
                Data::Missing,
                Classification::DictionaryMissingResponse,
            ),
            (
                Object::Dictionary,
                Data::Present(0),
                Classification::DictionaryEmptyResponse,
            ),
            (
                Object::Dictionary,
                Data::Present(MAX_FRAME_BYTES + 1),
                Classification::DictionaryOversizedResponse,
            ),
            (
                Object::Dictionary,
                Data::Present(MAX_FRAME_BYTES),
                Classification::DictionaryResponse,
            ),
        ] {
            assert_eq!(
                classify_mac_xpc_reply_v1(object, data, MAX_FRAME_BYTES),
                expected
            );
        }
    }

