#[cfg(target_os = "macos")]
impl Drop for MacRetirementActivationGuardV2 {
    fn drop(&mut self) {
        // SAFETY: this descriptor is owned by the guard and the lock is released only on drop.
        let _ = unsafe { libc::flock(self.root.as_raw_fd(), libc::LOCK_UN) };
    }
}

